# 1) Nginx 作为自建边缘缓存：缓存键 + 回源合并 + stale-while-revalidate
proxy_cache_path /data/cache levels=1:2 keys_zone=edge:200m max_size=50g inactive=7d use_temp_path=off;

upstream origin_https {
    server origin.example.com:443;
    keepalive 64;
}

server {
    listen 443 ssl;
    http2 on;  # Nginx 1.25.1+ 推荐写法，避免 listen ... http2 的弃用告警
    server_name cdn.example.com;

    location ~* \.(?:js|css|png|jpg|woff2)$ {
        proxy_pass https://origin_https;
        proxy_set_header Host origin.example.com;
        proxy_ssl_server_name on;
        proxy_ssl_name origin.example.com;

        # 缓存键只纳入白名单 query，避免 utm_* / 时间戳把缓存切碎
        proxy_cache edge;
        proxy_cache_key "$scheme://$host$uri?v=$arg_v";
        proxy_cache_valid 200 301 7d;
        proxy_cache_valid 404 410 30s;                 # 短 TTL 负缓存防穿透
        proxy_cache_lock on;                          # 回源合并：同一 key 只放一个回源
        proxy_cache_lock_timeout 5s;
        proxy_cache_use_stale updating error timeout http_500 http_502 http_503 http_504;
        proxy_cache_background_update on;             # 过期先返回旧响应，后台刷新

        add_header X-Cache-Status $upstream_cache_status always;  # HIT/MISS/EXPIRED/STALE/UPDATING
        add_header Cache-Control "public, max-age=31536000, immutable";
    }
}

# 2) 上线前验证配置与命中证据
nginx -t -c /etc/nginx/nginx.conf
curl -I -H 'Pragma: ' https://cdn.example.com/app.8f3a.js
# 关注头：X-Cache-Status、Age、Cache-Control、ETag

# 3) 厂商 refresh / preload API 必须按官方签名方式调用
# 不要把未签名 curl 当成可运行脚本；大促前先 preload 热点资源并验证 HIT，再切流或 refresh 入口。
